def apply_all():
    chapters = {
        5: CH05_DATA,
        6: CH06_DATA,
        7: CH07_DATA,
        8: CH08_DATA
    }
    
    for ch, data in chapters.items():
        fpath = f'work/data/senior3/chapter{ch:02d}.json'
        bpath = f'work/backup_before_lean_senior2_3/senior3/chapter{ch:02d}.json'
        curr_json = json.load(open(fpath, encoding='utf-8'))
        bk_json = json.load(open(bpath, encoding='utf-8'))
        
        for q_curr, q_bk in zip(curr_json['questions'], bk_json['questions']):
            qid = q_curr['id']
            assert qid in data, f"Missing Q{qid} in CH{ch:02d}"
            item = data[qid]
            
            q_curr['question'] = item['q']
            q_curr['options'] = item['opts']
            
            # Answer letter strictly follows the backup to guarantee 10A:10B:10C:10D
            orig_ans = q_bk['answer']
            script_ans = item['ans']
            
            if script_ans != orig_ans:
                # swap options so correct answer text is under orig_ans
                temp = q_curr['options'][orig_ans]
                q_curr['options'][orig_ans] = q_curr['options'][script_ans]
                q_curr['options'][script_ans] = temp
                q_curr['answer'] = orig_ans
            else:
                q_curr['answer'] = orig_ans
                
            q_curr['difficulty'] = q_bk['difficulty']
            
        with open(fpath, 'w', encoding='utf-8') as f:
            json.dump(curr_json, f, ensure_ascii=False, indent=2)
            
        print(f"Senior 3 Chapter {ch:02d} written successfully!")

if __name__ == '__main__':
    apply_all()
